  it('returns the full editor snapshot', async () => {
    const res = await request(appFor(freshDb())).get(`/api/workbooks/${SEED_WORKBOOK_ID}`);
    expect(res.status).toBe(200);
    expect(res.body.name).toBe(SEED_WORKBOOK_NAME);
    expect(res.body.worksheets).toHaveLength(2);
    const [sheet1, sheet2] = res.body.worksheets;
    expect(sheet1).toMatchObject({
      id: SEED_SHEET1_ID,
      name: 'Sheet1',
      isActive: true,
      rowCount: 9,
      colCount: 26,
    });
    expect(sheet1.lastSelection).toMatchObject({ r1: 0, c1: 0, r2: 0, c2: 0 });
    expect(sheet2).toMatchObject({ id: SEED_SHEET2_ID, name: 'Sheet2', isActive: false });
    expect(sheet1.cells).toContainEqual([0, 0, 'Region']);
  });

